using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using PrintShop3D.Data;
using PrintShop3D.Models;

namespace PrintShop3D.Pages.Customers;

public class CreateModel : PageModel
{
    private readonly AppDbContext _db;
    public CreateModel(AppDbContext db) => _db = db;

    [BindProperty] public Customer Customer { get; set; } = new();

    public void OnGet() { }

        public async Task<IActionResult> OnPostAsync()
    {
        // Customer Code is generated by the system.
        ModelState.Remove("Customer.CustomerCode");

        if (!ModelState.IsValid)
            return Page();

        await using var transaction = await _db.Database.BeginTransactionAsync();

        try
        {
            // Temporary unique code so SQL Server can create the CustomerId.
            Customer.CustomerCode = $"TMP-{Guid.NewGuid():N}";

            Customer.CreatedAt = DateTime.Now;

            _db.Customers.Add(Customer);

            // First save generates CustomerId.
            await _db.SaveChangesAsync();

            // Generate the real customer code from the database ID.
            Customer.CustomerCode = $"CUS-{Customer.CustomerId:D6}";

            // Save the generated code.
            await _db.SaveChangesAsync();

            await transaction.CommitAsync();

            TempData["Success"] =
                $"Customer created successfully. Customer Code: {Customer.CustomerCode}";

            return RedirectToPage("Index");
        }
        catch (Microsoft.Data.SqlClient.SqlException ex)
        {
            await transaction.RollbackAsync();

            ModelState.AddModelError(
                string.Empty,
                "Could not save the customer: " + FriendlySqlError(ex)
            );

            return Page();
        }
    }
    

    public static string FriendlySqlError(Microsoft.Data.SqlClient.SqlException ex)
    {
        if (ex.Message.Contains("UQ_CUSTOMERS_CustomerCode"))
            return "That customer code already exists.";
        return "A database rule prevented this save. Please check the values entered.";
    }
}
